import{_ as t,o as r,c as a,a0 as n}from"./chunks/framework.D7EjqxMK.js";const p=JSON.parse('{"title":"多Agent协作架构","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/03_高级模式/04_多Agent协作架构.md","filePath":"06-agent/03_高级模式/04_多Agent协作架构.md"}'),o={name:"06-agent/03_高级模式/04_多Agent协作架构.md"};function g(l,e,s,i,h,_){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="多agent协作架构" tabindex="-1">多Agent协作架构 <a class="header-anchor" href="#多agent协作架构" aria-label="Permalink to &quot;多Agent协作架构&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块三 · 03_高级模式 · 第 4 节 <strong>难度</strong>：⭐⭐⭐ | <strong>前置知识</strong>：单Agent基础</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>**多Agent协作（Multi-Agent Collaboration）**是将复杂任务拆给多个专业化 Agent 协同完成。每个 Agent 有独立角色、工具和能力。</p><p>核心理念：<strong>分工 &gt; 全能</strong> — 让多个专门 Agent 比一个全能 Agent 更可靠。</p><hr><h2 id="_2-多agent-的三种架构模式" tabindex="-1">2. 多Agent 的三种架构模式 <a class="header-anchor" href="#_2-多agent-的三种架构模式" aria-label="Permalink to &quot;2. 多Agent 的三种架构模式&quot;">​</a></h2><p>| 模式 | 描述 | 适用场景 | |--|-|--|- | | <strong>Sequential</strong> | Agent A → Agent B → Agent C | 流水线任务 | | <strong>Hierarchical</strong> | Manager Agent → Worker Agents | 项目管理 | | <strong>Swarm</strong> | 多 Agent 并行 + 自主决策 | 分布式任务 |</p><hr><h2 id="_3-mcp-在各框架中的支持" tabindex="-1">3. MCP 在各框架中的支持 <a class="header-anchor" href="#_3-mcp-在各框架中的支持" aria-label="Permalink to &quot;3. MCP 在各框架中的支持&quot;">​</a></h2><p>| 框架 | MCP 原生支持 | 集成难度 | |--|-|--|- | | <strong>CrewAI</strong> | ✅ 原生 | 低 | <a href="https://docs.crewai.org.cn/en/mcp/dsl-integration" target="_blank" rel="noreferrer">CrewAI MCP</a> | | <strong>AutoGen + Agent FW</strong> | ✅ 原生 | 低 | <a href="https://llmmultiagent.com/blogs/autogen_mcp_blog" target="_blank" rel="noreferrer">AutoGen+MCP</a> | | <strong>OpenAI Agents SDK</strong> | ✅ 原生 | 低 | OpenAI 官方 | | <strong>LangChain</strong> | ✅ 通过扩展 | 中 | <a href="https://chatforest.com/guides/mcp-ai-frameworks-langchain-langgraph-crewai/" target="_blank" rel="noreferrer">ChatForest</a> | | <strong>自研</strong> | ✅ 完全可控 | 高 | - |</p><hr><h2 id="_4-参考资料" tabindex="-1">4. 参考资料 <a class="header-anchor" href="#_4-参考资料" aria-label="Permalink to &quot;4. 参考资料&quot;">​</a></h2><ul><li><a href="https://nicklaunches.com/blog/ai-agent-frameworks-comparison-2025/" target="_blank" rel="noreferrer">Comparing 5 AI Agent Frameworks</a></li><li><a href="https://llmmultiagent.com/blogs/autogen_mcp_blog" target="_blank" rel="noreferrer">AutoGen 与 MCP</a></li><li><a href="https://docs.crewai.org.cn/en/mcp/dsl-integration" target="_blank" rel="noreferrer">CrewAI MCP 文档</a></li><li><a href="https://truto.one/blog/handling-auth-tool-sharing-in-multi-agent-frameworks-via-mcp/" target="_blank" rel="noreferrer">MCP &amp; 多框架集成 (Truto)</a></li></ul>',15)])])}const m=t(o,[["render",g]]);export{p as __pageData,m as default};
